def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    template = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    if not template:
        return out

    r0 = min(r for r, c in template)
    c0 = min(c for r, c in template)
    base = {(r - r0, c - c0) for r, c in template}

    # Keep the original orientation first; reflections/rotations are alternatives
    # when a fragment cannot match the original orientation.
    orientations = []
    seen_shapes = set()
    for reflected in (False, True):
        for turns in range(4):
            pts = set()
            for r, c in base:
                if reflected:
                    c = -c
                for _ in range(turns):
                    r, c = c, -r
                pts.add((r, c))
            mr = min(r for r, c in pts)
            mc = min(c for r, c in pts)
            shape = frozenset((r - mr, c - mc) for r, c in pts)
            if shape not in seen_shapes:
                seen_shapes.add(shape)
                orientations.append(shape)

    by_color = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color not in (1, 4):
                by_color.setdefault(color, []).append((r, c))

    for color, points in by_color.items():
        n = len(points)
        point_index = {p: i for i, p in enumerate(points)}
        candidates = []

        for oi, shape in enumerate(orientations):
            sh = list(shape)
            for pr, pc in points:
                for sr, sc in sh:
                    top, left = pr - sr, pc - sc
                    if (top < 0 or left < 0 or
                            top + max(r for r, c in sh) >= h or
                            left + max(c for r, c in sh) >= w):
                        continue
                    mask = 0
                    for rr, cc in sh:
                        p = (top + rr, left + cc)
                        if p in point_index:
                            mask |= 1 << point_index[p]
                    if mask:
                        candidates.append((mask, oi, top, left, shape))

        # Remove duplicate placements.
        unique = {}
        for cand in candidates:
            key = (cand[0], cand[1], cand[2], cand[3])
            unique[key] = cand
        candidates = list(unique.values())

        full = (1 << n) - 1
        containing = [[] for _ in range(n)]
        for cand in candidates:
            for i in range(n):
                if cand[0] & (1 << i):
                    containing[i].append(cand)

        memo = {}
        def solve(mask):
            if mask == full:
                return ()
            if mask in memo:
                return memo[mask]

            # Branch on the uncovered point with the fewest useful placements.
            uncovered = [i for i in range(n) if not (mask >> i) & 1]
            i = min(uncovered, key=lambda j: sum(
                1 for c in containing[j] if c[0] & ~mask
            ))

            best = None
            for cand in containing[i]:
                newmask = mask | cand[0]
                if newmask == mask:
                    continue
                rest = solve(newmask)
                selection = (cand,) + rest
                key = (len(selection),
                       tuple(sorted((x[1], x[2], x[3]) for x in selection)))
                if best is None or key < best[0]:
                    best = (key, selection)

            memo[mask] = best[1] if best is not None else ()
            return memo[mask]

        for _, oi, top, left, shape in solve(0):
            for rr, cc in shape:
                r, c = top + rr, left + cc
                if 0 <= r < h and 0 <= c < w:
                    out[r][c] = color

    return out
